        <label v-else>租户编码<input v-model="authForm.tenantCode" required placeholder="demo" /></label>
        <label>用户名<input v-model="authForm.username" required placeholder="warehouse" autocomplete="username" /></label>
        <label>密码<input v-model="authForm.password" required type="password" placeholder="请输入密码" autocomplete="current-password" /></label>
        <small v-if="authError" class="pda-login-error">{{ authError }}</small>
        <button class="pda-login-button" :disabled="authLoading"><span>{{ authLoading ? '正在验证身份…' : '进入工作台' }}</span><AppIcon name="arrowUpRight" :size="17" /></button>
        <div class="login-card-foot"><span><AppIcon name="shield" :size="13" /> 租户级数据隔离</span><span>Need help?</span></div>
      </form>
    </div>
  </div>

  <div v-else class="pda-app">
