          <StatusPill :online="online" :syncing="syncing" :pending="pendingCount" @click="openHistory" />
          <button class="header-user" type="button" @click="navigateTo('profile')"><span class="pda-avatar">{{ userInitial }}</span><span><b>{{ displayName }}</b><small>{{ userRole }}</small></span><AppIcon name="chevron" :size="14" /></button>
        </div>
      </header>

      <main class="pda-main">
        <section v-if="current === 'home'" class="home-view">
          <div class="home-intro">
            <div><span class="home-intro-date">{{ todayText }} · {{ online ? '现场终端在线' : '当前处于离线模式' }}</span><h1>你好，{{ displayName }}<span class="wave">✦</span></h1><p>这是你的现场运营工作台，今天也保持每一步清晰可控。</p></div>
            <button class="refresh-button" type="button" :disabled="loadingData" @click="loadData"><AppIcon name="refresh" :size="15" :class="{ spin: loadingData }" />{{ loadingData ? '刷新中…' : '刷新数据' }}</button>
          </div>

          <div class="home-overview-grid">
            <QuickActionPanel :operation-modes="operationModes" @open="openScanner()" @select="selectOperation" />
            <section class="home-kpi-panel">
              <SectionHeader eyebrow="TODAY / LIVE" title="运营概览" action-label="事务记录" action-hint="→" @action="openHistory" />
              <div class="metric-grid">
                <MetricCard label="今日事务" :value="summary.todayTransactions ?? 0" caption="已完成库存动作" icon="activity" tone="blue" trend="+12%" />
                <MetricCard label="库存 SKU" :value="summary.inventorySkus ?? 0" caption="当前可用物料" icon="package" tone="teal" />
                <MetricCard label="低库存" :value="summary.lowStock ?? 0" caption="需要关注的物料" icon="zap" tone="amber" />
                <MetricCard label="待同步" :value="pendingCount" caption="离线作业队列" icon="refresh" tone="violet" />
              </div>
              <div class="operation-health">
                <div class="operation-health-heading"><span><i class="health-dot"></i>终端运行状态</span><b>{{ online ? 'HEALTHY' : 'OFFLINE' }}</b></div>
                <div class="health-progress"><span :style="{ width: online ? '92%' : '42%' }"></span></div>
                <div class="operation-health-meta"><span>数据连接</span><span>{{ online ? '实时同步中' : '等待网络恢复' }}</span></div>
              </div>
            </section>
          </div>

          <div class="home-content-grid">
            <section class="content-panel task-panel">
              <SectionHeader eyebrow="WORK CENTER" title="今日任务" :action-label="`${tasks.length} 项待处理`" action-hint="→" @action="openTasks" />
              <TaskList :tasks="tasks.slice(0, 5)" @open="openScanner" />
            </section>
            <section class="content-panel inventory-panel">
              <SectionHeader eyebrow="WAREHOUSE" title="库存速览" action-label="查看全部" action-hint="→" @action="navigateTo('inventory')" />
