                <button v-for="item in inventory.slice(0, 4)" :key="inventoryKey(item)" class="stock-row stock-row-button" type="button" @click="inspectInventory(item)">
                  <span class="stock-icon"><AppIcon name="package" :size="15" /></span><span class="stock-row-copy"><b>{{ item.material_name }}</b><small>{{ item.material_code }} · {{ item.location_code }}</small></span>
                  <span class="stock-quantity" :class="{ danger: isLowStock(item) }"><strong>{{ item.available_qty }}</strong><small>{{ item.unit }}</small></span><AppIcon name="chevron" :size="15" class="stock-arrow" />
                </button>
                <div v-if="!inventory.length" class="empty-operation"><AppIcon name="package" :size="16" />暂无库存数据</div>
              </div>
            </section>
          </div>
          <div v-if="pendingCount" class="offline-banner" role="status" @click="openHistory"><AppIcon name="refresh" :size="15" /><span>离线队列有 <b>{{ pendingCount }} 条</b>待同步，恢复网络后将自动提交</span><AppIcon name="chevron" :size="15" /></div>
        </section>

        <section v-else-if="current === 'scan'" class="scan-view">
          <div class="scan-title"><button type="button" @click="closeScanner"><AppIcon name="chevron" :size="22" /></button><div><span class="scan-title-kicker">FIELD OPERATIONS</span><h1>扫码作业</h1><small>{{ scanModeLabel }}</small></div><button class="light-button" :class="{ active: torchEnabled }" type="button" title="打开手电筒" @click="toggleFlash"><AppIcon name="sun" :size="20" /></button></div>
          <div class="camera-stage"><video ref="video" muted playsinline></video><div class="scan-overlay"><span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><div class="scan-line"></div><span class="scan-overlay-label">ALIGN BARCODE</span></div><div v-if="cameraError" class="camera-error"><span>!</span><b>{{ cameraError }}</b><small>请检查浏览器摄像头权限，或使用下方手动录入</small></div></div>
          <div class="scan-tip"><span class="tip-icon"><AppIcon name="scan" :size="15" /></span><span>{{ targetScanPending ? '请扫描目标库位条码' : '将条码放入框内，系统会自动识别' }}</span></div>
          <div class="manual-card"><label>{{ targetScanPending ? '无法扫码？手动输入库位' : '无法扫码？手动输入' }}</label><div><input v-model="manualCode" :placeholder="targetScanPending ? '输入目标库位编码' : '输入物料 / 工单 / 库位编码'" @keyup.enter="submitManual" /><button type="button" @click="submitManual">确认</button></div></div>

          <div v-if="scanLookup" class="scan-result-card">
            <div class="result-card-heading"><div><span class="result-kicker">SCAN RESULT</span><h3>{{ scanLookup.material?.material_name || scanLookup.code }}</h3></div><button type="button" @click="scanLookup = null"><AppIcon name="close" :size="17" /></button></div>
            <p v-if="scanLookup.material"><b>{{ scanLookup.material.material_code }}</b> · {{ scanLookup.material.warehouse_code }} / {{ scanLookup.material.location_code }}</p><p v-else class="muted-text">未登记为物料条码，可继续核对编码或重新扫描。</p>
            <div v-if="scanLookup.material" class="result-stock"><span>可用库存 <b>{{ scanLookup.material.available_qty }} {{ scanLookup.material.unit }}</b></span><span>批次 <b>{{ scanLookup.material.batch_no || '—' }}</b></span></div>
            <div v-if="scanLookup.trace?.length" class="trace-list"><small>最近追溯记录</small><div v-for="row in scanLookup.trace.slice(-3).reverse()" :key="row.transaction_no"><span>{{ transactionLabel(row.transaction_type) }}</span><b>{{ row.quantity }} {{ row.unit }}</b><time>{{ formatDate(row.created_at) }}</time></div></div>
          </div>

          <div v-if="operationDraft" class="operation-card">
            <div class="operation-card-heading"><div><span class="result-kicker">{{ operationLabel(operationDraft.mode) }}</span><h3>确认现场作业</h3></div><button type="button" @click="cancelDraft"><AppIcon name="close" :size="17" /></button></div>
            <div class="material-summary"><span class="stock-icon"><AppIcon name="package" :size="15" /></span><div><b>{{ operationDraft.materialName }}</b><small>{{ operationDraft.materialCode }} · {{ operationDraft.batchNo || '无批次' }}</small></div></div>
            <div v-if="operationDraft.mode !== 'quality'" class="operation-location"><span><small>{{ outboundMode ? '来源仓库 / 库位' : '目标仓库 / 库位' }}</small><b>{{ operationDraft.warehouseCode }} / {{ outboundMode ? operationDraft.sourceLocationCode : operationDraft.targetLocationCode || '待确认' }}</b></span><button v-if="targetRequired" class="outline-button" type="button" @click="startTargetScan"><AppIcon name="scan" :size="13" />扫目标库位</button></div>
            <div v-if="operationDraft.mode === 'quality'" class="quality-mobile-card"><div v-if="!operationDraft.qualityLotId" class="quality-mobile-hint">扫描后先创建检验批；系统会自动匹配已发布的来料检验计划。</div><label>批次号<input v-model="operationDraft.batchNo" placeholder="请输入来料批次" /></label><label v-if="!operationDraft.qualityLotId">来源单号<input v-model="operationDraft.sourceDocNo" placeholder="收料单 / 送货单号" /></label><div v-for="item in operationDraft.qualityItems || []" :key="item.item_id" class="quality-mobile-item"><span><b>{{ item.characteristic_name }}</b><small>{{ item.standard_text || `${item.lower_limit ?? '-'} ~ ${item.upper_limit ?? '-'}` }}</small></span><input v-if="item.result_type === 'QUANTITATIVE'" v-model="item.resultValue" type="number" placeholder="录入数值" /><select v-else v-model="item.resultStatus"><option value="">未判定</option><option value="PASS">合格</option><option value="FAIL">不合格</option></select></div></div>
            <div v-else class="form-grid"><label>{{ operationDraft.mode === 'adjust' ? '调整数量（正数增加，负数减少）' : operationDraft.mode === 'count' ? '实盘数量' : '作业数量' }}<input v-if="operationDraft.mode === 'adjust'" v-model="operationDraft.adjustment" type="number" inputmode="numeric" placeholder="例如：-2" /><input v-else v-model.number="operationDraft.quantity" type="number" min="1" step="1" inputmode="numeric" /></label><label v-if="targetRequired">目标库位<input v-model="operationDraft.targetLocationCode" placeholder="扫描或输入库位" /></label><label v-if="operationDraft.mode === 'receipt' || operationDraft.mode === 'return' || operationDraft.mode === 'finished'">批次号<input v-model="operationDraft.batchNo" placeholder="可选" /></label></div>
            <label class="full-field">备注 / 原因<input v-model="operationDraft.remark" placeholder="可选" /></label><p v-if="operationError" class="inline-error">{{ operationError }}</p><button class="submit-operation" type="button" :disabled="submitting" @click="submitOperation">{{ submitting ? '提交中…' : operationDraft.mode === 'count' ? '提交盘点' : operationDraft.mode === 'quality' && operationDraft.qualityLotId ? '提交检验判定' : operationDraft.mode === 'quality' ? '创建检验批' : '确认提交' }}</button>
          </div>

          <div v-if="reportDraft" class="operation-card"><div class="operation-card-heading"><div><span class="result-kicker">现场报工</span><h3>{{ reportDraft.order_no }}</h3></div><button type="button" @click="reportDraft = null"><AppIcon name="close" :size="17" /></button></div><p class="report-meta">{{ reportDraft.material_name || '生产工单' }} · 计划 {{ reportDraft.plan_qty }} · 已完成 {{ reportDraft.completed_qty }}</p><label class="full-field">本次报工数量<input v-model.number="reportDraft.quantity" type="number" min="1" step="1" inputmode="numeric" /></label><p v-if="operationError" class="inline-error">{{ operationError }}</p><button class="submit-operation" type="button" :disabled="submitting" @click="submitReport">{{ submitting ? '提交中…' : '确认报工' }}</button></div>
          <div class="recent-scans"><div class="section-title"><h3>最近扫描</h3><button type="button" @click="recentScans = []">清空</button></div><div v-for="item in recentScans" :key="item.id" class="recent-row"><span class="recent-check"><AppIcon name="check" :size="11" /></span><span><b>{{ item.code }}</b><small>{{ item.result }}</small></span><time>{{ item.time }}</time></div></div>
        </section>

        <section v-else-if="current === 'inventory'" class="inventory-view"><div class="page-title"><div><small>WAREHOUSE / INVENTORY</small><h1>库存查询</h1><p>按物料、批次和库位快速定位现场库存。</p></div><button class="scan-mini" type="button" @click="openScanner('inventory')"><AppIcon name="scan" :size="14" />扫码查询</button></div><div class="search-box"><AppIcon name="search" :size="16" /><input v-model="inventoryKeyword" placeholder="搜索物料编码、名称、批次或库位" /></div><div class="inventory-filter"><button v-for="filter in inventoryFilters" :key="filter.key" type="button" :class="{ active: inventoryFilter === filter.key }" @click="inventoryFilter = filter.key">{{ filter.label }}</button></div><div v-if="inventoryDetail" class="inventory-detail-card"><div class="result-card-heading"><div><span class="result-kicker">INVENTORY DETAIL</span><h3>{{ inventoryDetail.material_name }}</h3></div><button type="button" @click="inventoryDetail = null"><AppIcon name="close" :size="17" /></button></div><p>{{ inventoryDetail.material_code }} · {{ inventoryDetail.warehouse_code }} / {{ inventoryDetail.location_code }}</p><div class="detail-metrics"><span><small>可用</small><b>{{ inventoryDetail.available_qty }} {{ inventoryDetail.unit }}</b></span><span><small>锁定</small><b>{{ inventoryDetail.locked_qty || 0 }} {{ inventoryDetail.unit }}</b></span><span><small>预留</small><b>{{ inventoryDetail.reserved_qty || 0 }} {{ inventoryDetail.unit }}</b></span></div><div v-if="inventoryTrace.length" class="trace-list"><small>批次追溯</small><div v-for="row in inventoryTrace.slice(-5).reverse()" :key="row.transaction_no"><span>{{ transactionLabel(row.transaction_type) }}</span><b>{{ row.quantity }} {{ row.unit }}</b><time>{{ formatDate(row.created_at) }}</time></div></div></div><div class="mobile-stock-list"><button v-for="item in filteredInventory" :key="inventoryKey(item)" class="mobile-stock-card" type="button" @click="inspectInventory(item)"><div class="stock-card-top"><span class="stock-icon"><AppIcon name="package" :size="15" /></span><span><b>{{ item.material_name }}</b><small>{{ item.material_code }}</small></span><span class="batch-tag">{{ item.batch_no || '无批次' }}</span></div><div class="stock-card-info"><span><small>仓库 / 库位</small><b>{{ item.warehouse_code }} · {{ item.location_code }}</b></span><span class="align-right"><small>可用库存</small><strong :class="{ danger: isLowStock(item) }">{{ item.available_qty }} {{ item.unit }}</strong></span></div><div class="stock-card-foot"><span>锁定 {{ item.locked_qty || 0 }} {{ item.unit }}</span><span v-if="isLowStock(item)" class="danger-text">低于安全库存 {{ item.safety_stock }}</span><span v-else class="ok-text">库存正常</span></div></button><div v-if="!filteredInventory.length" class="empty-operation">没有匹配的库存记录</div></div></section>

        <ExceptionPanel v-else-if="current === 'exceptions'" @close="navigateTo('home')" />
        <section v-else-if="current === 'tasks'" class="profile-view task-page"><div class="page-title"><div><small>WORK CENTER</small><h1>现场任务</h1><p>优先处理需要现场确认的生产工单。</p></div><button class="text-back" type="button" @click="current = 'home'">返回工作台</button></div><TaskList :tasks="tasks" @open="openScanner" /></section>

        <section v-else-if="current === 'history'" class="profile-view history-view"><div class="page-title"><div><small>LEDGER / AUDIT TRAIL</small><h1>事务记录</h1><p>查看库存事务、作业单据与盘点记录。</p></div><button class="text-back" type="button" @click="current = 'home'">返回工作台</button></div><div v-if="pendingCount" class="offline-banner"><AppIcon name="refresh" :size="15" />待同步 {{ pendingCount }} 条，{{ online ? '正在自动重试' : '恢复网络后自动重试' }}</div><div class="history-tabs"><button type="button" :class="{ active: historyTab === 'transactions' }" @click="historyTab = 'transactions'">库存事务</button><button type="button" :class="{ active: historyTab === 'documents' }" @click="historyTab = 'documents'">作业单据</button><button type="button" :class="{ active: historyTab === 'counts' }" @click="historyTab = 'counts'">盘点记录</button></div><div class="history-list"><div v-for="row in historyRows" :key="row.id || row.transaction_no || row.count_no" class="history-row"><span class="history-type">{{ historyTab === 'transactions' ? transactionLabel(row.transaction_type) : historyTab === 'documents' ? row.document_type : row.count_type }}</span><div><b>{{ row.material_name || row.document_no || row.count_no }}</b><small>{{ row.material_code || row.status }} · {{ row.warehouse_code || '' }} {{ row.location_code || '' }}</small></div><strong v-if="historyTab === 'transactions'">{{ row.quantity }} {{ row.unit }}</strong><time>{{ formatDate(row.created_at || row.submitted_at) }}</time></div><div v-if="!historyRows.length" class="empty-operation">暂无记录</div></div></section>

        <section v-else class="profile-view"><div class="profile-hero"><span class="big-avatar">{{ userInitial }}</span><span class="profile-kicker">CURRENT OPERATOR</span><h1>{{ displayName }}</h1><small>{{ userRole }} · 当前租户业务用户</small></div><div class="profile-menu"><button type="button" @click="openTasks"><AppIcon name="task" :size="17" /><span><b>现场任务</b><small>{{ tasks.length }} 项待处理工单</small></span><AppIcon name="chevron" :size="16" /></button><button type="button" @click="openHistory"><AppIcon name="clipboard" :size="17" /><span><b>事务记录</b><small>库存、作业单据与盘点记录</small></span><AppIcon name="chevron" :size="16" /></button><button type="button" @click="openScanner('general')"><AppIcon name="scan" :size="17" /><span><b>条码查询</b><small>扫码查看库存与批次追溯</small></span><AppIcon name="chevron" :size="16" /></button><button type="button" @click="logout"><AppIcon name="logout" :size="17" /><span><b>退出登录</b><small>清除当前终端登录信息</small></span><AppIcon name="chevron" :size="16" /></button></div><div v-if="pendingCount" class="profile-outbox"><b>离线补传队列</b><span>{{ pendingCount }} 条作业等待同步</span><button type="button" @click="flushOfflineQueue">立即同步</button></div></section>
      </main>
    </div>

    <div v-if="notice" class="pda-notice" :class="notice.type"><AppIcon :name="notice.type === 'error' ? 'close' : notice.type === 'warning' ? 'zap' : 'check'" :size="15" />{{ notice.text }}</div>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { request } from './api'
import { detectBarcode, openCamera, stopCamera } from './services/scanner'
import { enqueueOperation, isNetworkError, listQueuedOperations, removeQueuedOperation } from './services/offlineQueue'
import AppIcon from './components/AppIcon.vue'
import BrandMark from './components/BrandMark.vue'
import MetricCard from './components/MetricCard.vue'
import QuickActionPanel from './components/QuickActionPanel.vue'
import SectionHeader from './components/SectionHeader.vue'
import StatusPill from './components/StatusPill.vue'
import TaskList from './components/TaskList.vue'
import WorkspaceNav from './components/WorkspaceNav.vue'
import ExceptionPanel from './components/ExceptionPanel.vue'

const authenticated = ref(Boolean(localStorage.getItem('polaris-token')))
const authLoading = ref(false)
const authError = ref('')
const tenantOptions = ref([])
const authForm = ref({ tenantCode: localStorage.getItem('polaris-tenant-code') || 'demo', username: '', password: '' })
const currentUser = computed(() => { try { return JSON.parse(localStorage.getItem('polaris-user') || '{}') } catch { return {} } })
const displayName = computed(() => currentUser.value.displayName || currentUser.value.username || '操作员')
const userRole = computed(() => currentUser.value.roleCode || 'operator')
const userInitial = computed(() => String(displayName.value).slice(0, 1))
const todayText = new Intl.DateTimeFormat('zh-CN', { month: '2-digit', day: '2-digit', weekday: 'short' }).format(new Date())

const operationModes = [
  { key: 'receipt', label: '收料入库', icon: '⇩', transactionType: 'RECEIPT' }, { key: 'issue', label: '生产领料', icon: '⇧', transactionType: 'ISSUE' },
  { key: 'return', label: '生产退料', icon: '↩', transactionType: 'RETURN' }, { key: 'putaway', label: '合格上架', icon: '⌂', transactionType: 'PUTAWAY' },
  { key: 'transfer', label: '调拨移库', icon: '⇄', transactionType: 'MOVE' }, { key: 'count', label: '扫码盘点', icon: '▤', transactionType: 'COUNT' },
  { key: 'finished', label: '成品入库', icon: '▣', transactionType: 'FINISHED_RECEIPT' }, { key: 'sales', label: '销售出库', icon: '↗', transactionType: 'SALES_OUTBOUND' },
  { key: 'scrap', label: '报废出库', icon: '×', transactionType: 'SCRAP' }, { key: 'adjust', label: '库存调整', icon: '±', transactionType: 'ADJUSTMENT' },
  { key: 'quality', label: '来料检验', icon: '✓', transactionType: 'QUALITY' },
  { key: 'exception', label: '上报异常', icon: '!', transactionType: 'EXCEPTION' }
]
const inventoryFilters = [{ key: 'ALL', label: '全部' }, { key: 'RAW', label: '原材料' }, { key: 'FINISHED', label: '成品' }, { key: 'LOW', label: '低库存' }]
const operationLabels = Object.fromEntries(operationModes.map(mode => [mode.key, mode.label]))
const transactionLabels = { RECEIPT: '收料入库', ISSUE: '生产领料', RETURN: '生产退料', PUTAWAY: '合格上架', MOVE: '调拨移库', COUNT: '扫码盘点', FINISHED_RECEIPT: '成品入库', SALES_OUTBOUND: '销售出库', SCRAP: '报废出库', ADJUSTMENT: '库存调整', LOCK: '库存锁定', UNLOCK: '库存解锁', RESERVE: '库存预留', RELEASE: '释放预留', FREEZE: '冻结库存', UNFREEZE: '解冻库存' }

const current = ref('home')
const video = ref(null); const stream = ref(null); const detectionTimer = ref(null); const torchEnabled = ref(false); const cameraError = ref(''); const manualCode = ref(''); const scanMode = ref('general'); const lastCode = ref(''); const processingScan = ref(false); const targetScanPending = ref(false); const recentScans = ref([])
const inventory = ref([]); const locations = ref([]); const barcodes = ref([]); const workOrders = ref([]); const summary = ref({}); const inventoryKeyword = ref(''); const inventoryFilter = ref('ALL'); const inventoryDetail = ref(null); const inventoryTrace = ref([]); const scanLookup = ref(null); const operationDraft = ref(null); const reportDraft = ref(null); const operationError = ref(''); const submitting = ref(false); const loadingData = ref(false); const online = ref(globalThis.navigator?.onLine !== false); const syncing = ref(false); const pendingCount = ref(listQueuedOperations().length); const notice = ref(null); const historyTab = ref('transactions'); const transactions = ref([]); const documents = ref([]); const counts = ref([])
let noticeTimer

const tasks = computed(() => workOrders.value.filter(item => ['IN_PROGRESS', 'PLANNED', 'PENDING_APPROVAL'].includes(item.status)).map(order => ({ id: order.id, title: order.status === 'PENDING_APPROVAL' ? '工单待审批' : '工单现场报工', subtitle: `${order.order_no} · ${order.work_center || '未分配工作中心'}`, count: Math.max(0, Number(order.plan_qty || 0) - Number(order.completed_qty || 0)), unit: '台待报', tone: 'blue', icon: '◉', type: 'report' })))
const currentPageTitle = computed(() => ({ home: '工作台', scan: '扫码作业', inventory: '库存查询', exceptions: '现场异常', tasks: '现场任务', history: '事务记录', profile: '我的账户' }[current.value] || '现场作业'))
const scanModeLabel = computed(() => ({ general: '扫描物料、工单或库位条码', inventory: '库存查询 · 扫描物料条码', report: '现场报工 · 扫描工单条码', ...Object.fromEntries(operationModes.map(mode => [mode.key, `${mode.label} · 扫描物料条码`])) }[scanMode.value] || '扫码作业'))
const targetRequired = computed(() => ['receipt', 'return', 'putaway', 'transfer', 'finished'].includes(operationDraft.value?.mode))
const outboundMode = computed(() => ['issue', 'sales', 'scrap'].includes(operationDraft.value?.mode))
const historyRows = computed(() => historyTab.value === 'transactions' ? transactions.value : historyTab.value === 'documents' ? documents.value : counts.value)
const filteredInventory = computed(() => inventory.value.filter(item => { const keyword = inventoryKeyword.value.trim().toLowerCase(); const matched = !keyword || `${item.material_code}${item.material_name}${item.batch_no || ''}${item.location_code || ''}`.toLowerCase().includes(keyword); const type = String(item.material_type || '').toUpperCase(); const typeMatched = inventoryFilter.value === 'ALL' || inventoryFilter.value === 'LOW' ? true : inventoryFilter.value === type || (inventoryFilter.value === 'FINISHED' && ['FG', 'FINISHED', 'SEMI'].includes(type)); return matched && typeMatched && (inventoryFilter.value !== 'LOW' || isLowStock(item)) }))

function navigateTo(view) { current.value = view; if (view === 'history') loadHistory() }
function selectOperation(mode) { if (mode === 'exception') navigateTo('exceptions'); else openScanner(mode) }
function inventoryKey(item) { return `${item.material_code}-${item.warehouse_code}-${item.location_code}-${item.batch_no || '-'}` }
function isLowStock(item) { return Number(item.available_qty || 0) < Number(item.safety_stock || 0) }
function operationLabel(mode) { return operationLabels[mode] || '扫码作业' }
function transactionLabel(type) { return transactionLabels[type] || type || '库存事务' }
function formatDate(value) { if (!value) return '—'; const date = new Date(String(value).replace(' ', 'T')); return Number.isNaN(date.getTime()) ? String(value).slice(0, 16) : date.toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) }
function showNotice(text, type = 'success') { notice.value = { text, type }; clearTimeout(noticeTimer); noticeTimer = window.setTimeout(() => { notice.value = null }, 3200) }

async function loadTenants() { try { tenantOptions.value = await request('/auth/tenants') || []; if (!authForm.value.tenantCode && tenantOptions.value[0]) authForm.value.tenantCode = tenantOptions.value[0].tenant_code } catch {} }
async function login() { authLoading.value = true; authError.value = ''; try { const data = await request('/auth/login', { method: 'POST', body: JSON.stringify(authForm.value) }); localStorage.setItem('polaris-token', data.token); localStorage.setItem('polaris-user', JSON.stringify(data.user)); localStorage.setItem('polaris-tenant', JSON.stringify(data.tenant)); localStorage.setItem('polaris-tenant-code', data.tenant.code); authenticated.value = true; await loadData(); await flushOfflineQueue() } catch (error) { authError.value = error.message || '登录失败' } finally { authLoading.value = false } }
function logout() { stopCamera(stream.value); stream.value = null; localStorage.removeItem('polaris-token'); localStorage.removeItem('polaris-user'); localStorage.removeItem('polaris-tenant'); authenticated.value = false; current.value = 'home' }
async function loadData() { if (!authenticated.value) return; loadingData.value = true; try { const [inventoryData, workOrderData, barcodeData, locationData, summaryData] = await Promise.all([request('/warehouse/inventory'), request('/manufacturing/work-orders'), request('/warehouse/barcodes'), request('/warehouse/locations'), request('/warehouse/summary')]); inventory.value = inventoryData || []; workOrders.value = workOrderData || []; barcodes.value = barcodeData || []; locations.value = locationData || []; summary.value = summaryData || {} } catch (error) { showNotice(error.message || '数据加载失败', 'error') } finally { loadingData.value = false; pendingCount.value = listQueuedOperations().length } }
async function loadHistory() { try { [transactions.value, documents.value, counts.value] = await Promise.all([request('/warehouse/transactions?limit=50'), request('/warehouse/documents'), request('/warehouse/counts')]) } catch (error) { showNotice(error.message || '记录加载失败', 'error') } }
function openHistory() { navigateTo('history') }
function openTasks() { navigateTo('tasks') }

async function openScanner(mode = 'general') { if (stream.value) stopCamera(stream.value); scanMode.value = mode; current.value = 'scan'; cameraError.value = ''; lastCode.value = ''; targetScanPending.value = false; operationDraft.value = null; reportDraft.value = null; scanLookup.value = null; operationError.value = ''; await nextTick(); try { stream.value = await openCamera(video.value); detectLoop() } catch (error) { cameraError.value = error.message || '摄像头暂不可用' } }
function scheduleDetect() { clearTimeout(detectionTimer.value); if (current.value === 'scan') detectionTimer.value = window.setTimeout(detectLoop, 500) }
async function detectLoop() { if (current.value !== 'scan' || !video.value) return; if (!processingScan.value && !targetScanPending.value && !operationDraft.value && !reportDraft.value) { try { const code = await detectBarcode(video.value); if (code && code !== lastCode.value) { lastCode.value = code; await handleCode(code); window.setTimeout(() => { if (lastCode.value === code) lastCode.value = '' }, 1800) } } catch {} } scheduleDetect() }
function closeScanner() { clearTimeout(detectionTimer.value); stopCamera(stream.value); stream.value = null; torchEnabled.value = false; targetScanPending.value = false; operationDraft.value = null; reportDraft.value = null; current.value = 'home' }
async function toggleFlash() { const track = stream.value?.getVideoTracks?.()[0]; const capabilities = track?.getCapabilities?.(); if (!track || !capabilities?.torch) { cameraError.value = '当前设备或浏览器不支持闪光灯控制'; return } try { torchEnabled.value = !torchEnabled.value; await track.applyConstraints({ advanced: [{ torch: torchEnabled.value }] }) } catch { torchEnabled.value = false; cameraError.value = '闪光灯控制失败，请使用设备系统手电筒' } }

function recordScan(code) { recentScans.value.unshift({ id: `${code}-${Date.now()}`, code, result: targetScanPending.value ? '扫描目标库位' : scanModeLabel.value, time: new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }); recentScans.value = recentScans.value.slice(0, 8); if (navigator.vibrate) navigator.vibrate(80) }
function findMaterial(parsed, code) { const barcode = barcodes.value.find(item => item.barcode === code); const materialCode = parsed?.material_code || barcode?.material_code || code; const batchNo = parsed?.batch_no || barcode?.batch_no; const parsedInventory = parsed?.inventory?.find?.(item => (!batchNo || item.batch_no === batchNo)); return parsedInventory || inventory.value.find(item => item.material_code === materialCode && (!batchNo || item.batch_no === batchNo)) || inventory.value.find(item => item.material_code === materialCode) }
async function parseCode(code) { let parsed = { barcode: code, found: false }; try { parsed = await request(`/warehouse/barcodes/parse?barcode=${encodeURIComponent(code)}`) || parsed } catch {} const material = findMaterial(parsed, code); const location = parsed.location_code || locations.value.find(item => item.location_code === code)?.location_code || (parsed.found && parsed.barcode_type === 'LOCATION' ? code : ''); return { ...parsed, material, location } }
async function buildLookup(code, parsed) { let trace = parsed.trace || []; if (!trace.length && parsed.material) { try { trace = await request(`/warehouse/trace?materialCode=${encodeURIComponent(parsed.material.material_code)}&batchNo=${encodeURIComponent(parsed.material.batch_no || '')}`) || [] } catch {} } scanLookup.value = { code, material: parsed.material, trace, inventory: parsed.inventory || (parsed.material ? [parsed.material] : []) } }
function makeDraft(mode, material) { return { mode, transactionType: operationLabels[mode] ? operationModes.find(item => item.key === mode).transactionType : mode, materialCode: material.material_code, materialName: material.material_name, unit: material.unit, warehouseCode: material.warehouse_code, sourceLocationCode: material.location_code, targetWarehouseCode: material.warehouse_code, targetLocationCode: mode === 'adjust' ? material.location_code : ['issue', 'sales', 'scrap'].includes(mode) ? material.location_code : '', batchNo: material.batch_no || '', quantity: 1, adjustment: '', remark: '' } }
function startTargetScan() { targetScanPending.value = true; operationError.value = ''; showNotice('请扫描目标库位条码', 'info') }
function cancelDraft() { operationDraft.value = null; reportDraft.value = null; targetScanPending.value = false; operationError.value = '' }
async function handleCode(code) { const cleanCode = String(code || '').trim(); if (!cleanCode || processingScan.value) return; processingScan.value = true; recordScan(cleanCode); try { const parsed = await parseCode(cleanCode); if (targetScanPending.value) { if (!parsed.location) throw new Error('未识别到目标库位，请扫描已登记的库位条码或手动输入库位编码'); operationDraft.value.targetLocationCode = parsed.location; targetScanPending.value = false; showNotice(`目标库位已设置为 ${parsed.location}`, 'success'); return } if (scanMode.value === 'general' || scanMode.value === 'inventory') { await buildLookup(cleanCode, parsed); if (scanMode.value === 'inventory') current.value = 'scan'; return } if (scanMode.value === 'report') { const order = workOrders.value.find(item => item.order_no === cleanCode || item.order_no === parsed.source_doc_no); if (!order) throw new Error('未找到对应工单，请扫描工单号'); reportDraft.value = { ...order, quantity: 1 }; operationError.value = ''; return } const material = parsed.material; if (!material) throw new Error('未找到对应库存物料，请扫描物料编码或已登记条码'); operationDraft.value = makeDraft(scanMode.value, material); operationError.value = ''; scanLookup.value = null; showNotice(`已识别 ${material.material_code}，请确认数量后提交`, 'info') } catch (error) { operationError.value = error.message || '扫码处理失败'; showNotice(operationError.value, 'error') } finally { processingScan.value = false; scheduleDetect() } }
async function submitManual() { const code = manualCode.value.trim(); if (!code) return; manualCode.value = ''; await handleCode(code) }
function operationPayload(draft) { const adjustment = Number(draft.adjustment); const quantity = draft.mode === 'adjust' ? Math.abs(adjustment) : Number(draft.quantity); if (!Number.isInteger(quantity) || quantity <= 0) throw new Error(draft.mode === 'adjust' ? '调整数量不能为 0' : '数量必须是大于 0 的整数'); const source = draft.sourceLocationCode; const target = draft.targetLocationCode; const movesFromSource = ['putaway', 'transfer', 'issue', 'sales', 'scrap'].includes(draft.mode); if (targetRequired.value && !target) throw new Error('请先扫描或输入目标库位'); if (['putaway', 'transfer'].includes(draft.mode) && source === target) throw new Error('来源库位和目标库位不能相同'); const payload = { transactionType: draft.transactionType, materialCode: draft.materialCode, materialName: draft.materialName, unit: draft.unit, warehouseCode: draft.warehouseCode, locationCode: outboundMode.value ? source : target, fromWarehouseCode: draft.warehouseCode, fromLocationCode: movesFromSource ? source : null, toWarehouseCode: draft.targetWarehouseCode, toLocationCode: target, batchNo: draft.batchNo || null, quantity, remark: draft.remark || null, reasonCode: draft.mode === 'scrap' ? 'SCRAP' : draft.mode === 'count' ? 'COUNT' : null, idempotencyKey: `pda-${Date.now()}-${Math.random().toString(16).slice(2)}` }; if (draft.mode === 'adjust') payload.adjustment = adjustment; return payload }
async function submitOperation() { operationError.value = ''; submitting.value = true; try { const draft = operationDraft.value; if (draft.mode === 'quality') { await submitQualityOperation(draft); return } const payload = draft.mode === 'count' ? { warehouseCode: draft.warehouseCode, locationCode: draft.sourceLocationCode, materialCode: draft.materialCode, batchNo: draft.batchNo || null, countQty: Number(draft.quantity) } : operationPayload(draft); await submitOrQueue(draft.mode === 'count' ? '/warehouse/counts/quick' : '/warehouse/transactions', payload, operationLabel(draft.mode)); operationDraft.value = null; targetScanPending.value = false; await loadData() } catch (error) { operationError.value = error.message || '提交失败' } finally { submitting.value = false } }
async function submitQualityOperation(draft) { if (!draft.qualityLotId) { const lot = await request('/quality/lots', { method: 'POST', body: JSON.stringify({ inspectionType: 'INCOMING', materialCode: draft.materialCode, materialName: draft.materialName, batchNo: draft.batchNo || null, sampleQty: 1, sourceType: 'PDA', sourceDocNo: draft.sourceDocNo || null }) }); const started = await request(`/quality/lots/${lot.id}/start`, { method: 'POST' }); if (!started.items?.length) throw new Error('未匹配到已发布检验计划，请先在质量管理中维护计划'); draft.qualityLotId = started.id; draft.qualityItems = started.items.map(item => ({ ...item, resultValue: '', resultText: '', resultStatus: '' })); showNotice('检验批已创建，请录入各检验项目结果', 'info'); return } const missing = (draft.qualityItems || []).some(item => item.required_flag !== 0 && !item.resultValue && !item.resultStatus); if (missing) throw new Error('请完成所有必检项目后再提交判定'); await request(`/quality/lots/${draft.qualityLotId}/results`, { method: 'POST', body: JSON.stringify({ items: draft.qualityItems.map(item => ({ itemId: item.item_id, resultValue: item.resultValue || undefined, resultText: item.resultStatus || undefined, resultStatus: item.resultStatus || undefined })) }) }); const result = await request(`/quality/lots/${draft.qualityLotId}/complete`, { method: 'POST' }); showNotice(`检验已完成：${result.status === 'PASSED' ? '合格' : '不合格'}`, result.status === 'PASSED' ? 'success' : 'warning'); operationDraft.value = null; await loadData() }
async function submitReport() { operationError.value = ''; submitting.value = true; try { const draft = reportDraft.value; const quantity = Number(draft.quantity); if (!Number.isInteger(quantity) || quantity <= 0) throw new Error('报工数量必须是大于 0 的整数'); await submitOrQueue(`/manufacturing/work-orders/${draft.id}/report`, { quantity }, '现场报工'); reportDraft.value = null; await loadData() } catch (error) { operationError.value = error.message || '报工失败' } finally { submitting.value = false } }
async function submitOrQueue(path, payload, label) { const options = { method: 'POST', body: JSON.stringify(payload) }; try { await request(path, options); showNotice(`${label}已提交`, 'success') } catch (error) { if (!isNetworkError(error)) throw error; enqueueOperation({ path, method: 'POST', body: options.body, label }); pendingCount.value = listQueuedOperations().length; showNotice(`${label}已加入离线补传队列`, 'warning') } }
async function flushOfflineQueue() { if (!authenticated.value || !online.value || syncing.value) return; const queue = listQueuedOperations(); if (!queue.length) { pendingCount.value = 0; return } syncing.value = true; try { for (const entry of queue) { try { await request(entry.path, { method: entry.method, body: entry.body }); removeQueuedOperation(entry.id) } catch (error) { if (isNetworkError(error)) break; showNotice(`${entry.label || '离线作业'}补传失败，请检查记录`, 'error'); break } } pendingCount.value = listQueuedOperations().length; if (!pendingCount.value) showNotice('离线作业已全部同步', 'success'); await loadData() } finally { syncing.value = false } }
async function inspectInventory(item) { inventoryDetail.value = item; inventoryTrace.value = []; try { inventoryTrace.value = await request(`/warehouse/trace?materialCode=${encodeURIComponent(item.material_code)}&batchNo=${encodeURIComponent(item.batch_no || '')}`) || [] } catch (error) { showNotice(error.message || '追溯记录加载失败', 'error') } }
function handleOnlineChange() { online.value = navigator.onLine; if (online.value) flushOfflineQueue() }

onMounted(async () => { window.addEventListener('online', handleOnlineChange); window.addEventListener('offline', handleOnlineChange); if (!authenticated.value) { await loadTenants(); return } try { await request('/auth/me'); await loadData(); await flushOfflineQueue() } catch (error) { localStorage.removeItem('polaris-token'); authenticated.value = false; authError.value = error.message || '登录已失效，请重新登录' } })
onBeforeUnmount(() => { clearTimeout(detectionTimer.value); clearTimeout(noticeTimer); stopCamera(stream.value); window.removeEventListener('online', handleOnlineChange); window.removeEventListener('offline', handleOnlineChange) })
</script>

